// Wire types. Mirrors `crates/mr-krabs-core/src/api.rs`.
// From M1 these are generated by tauri-specta; keep in sync until then.

export type ErrorCode = "VALIDATION" | "NOT_FOUND" | "UNKNOWN_COMMAND" | "INTERNAL" | "TRANSPORT";

export interface HealthDto {
  status: string;
  version: string;
  schemaVersion: number;
  latestSchemaVersion: number;
  dbPath: string | null;
}

/** Money on the wire. `minor` is a string on purpose: never do math with it in the UI. */
export interface MoneyDto {
  minor: string;
  currency: string;
  display: string;
}

export interface MoneyInput {
  amount: string;
  currency: string;
}
